-- Contact guard, server side. Mirrors src/lib/contactGuard.ts so a modified
-- app can't skip it; both are checked against src/test/fixtures/guard-cases.json.
-- Generated by scripts/gen-guard-sql.py: edit that script, not this file.

create or replace function app.number_word_digit(w text) returns text
language sql immutable as $$
  select case lower(w)
    when 'zero' then '0'
    when 'oh' then '0'
    when 'one' then '1'
    when 'two' then '2'
    when 'three' then '3'
    when 'four' then '4'
    when 'five' then '5'
    when 'six' then '6'
    when 'seven' then '7'
    when 'eight' then '8'
    when 'nine' then '9'
    when 'শূন্য' then '0'
    when 'শুন্য' then '0'
    when 'এক' then '1'
    when 'দুই' then '2'
    when 'তিন' then '3'
    when 'চার' then '4'
    when 'পাঁচ' then '5'
    when 'পাচ' then '5'
    when 'সাত' then '7'
    when 'আট' then '8'
    when 'ছয়' then '6'
    when 'নয়' then '9'
    when 'জিরো' then '0'
    when 'টু' then '2'
    when 'থ্রি' then '3'
    when 'ফোর' then '4'
    when 'ফাইভ' then '5'
    when 'সিক্স' then '6'
    when 'সেভেন' then '7'
    when 'এইট' then '8'
    when 'নাইন' then '9'
    when 'ওয়ান' then '1'
    else '' end
$$;

create or replace function app.run_digits(run text) returns text
language plpgsql immutable as $$
declare tok text; out text := '';
begin
  for tok in select (regexp_matches(run, '((?:[0-9০-৯]|(?<![A-Za-zঀ-৿])(?:three|seven|eight|শূন্য|শুন্য|সিক্স|সেভেন|ওয়ান|zero|four|five|nine|পাঁচ|জিরো|থ্রি|ফাইভ|নাইন|one|two|six|দুই|তিন|চার|পাচ|সাত|ছয়|নয়|ফোর|এইট|oh|এক|আট|টু)(?![A-Za-zঀ-৿])))', 'gi'))[1] loop
    if tok ~ '[0-9০-৯]' then
      out := out || translate(tok, '০১২৩৪৫৬৭৮৯', '0123456789');
    else
      out := out || app.number_word_digit(tok);
    end if;
  end loop;
  return out;
end $$;

-- Hides phone numbers written in digits, words, or a mix.
-- Returns {"text": …, "hit": true|false}.
create or replace function app.hide_phones(t text) returns jsonb
language plpgsql immutable as $$
declare run text; out text := t; hit boolean := false; before text;
begin
  for run in select (regexp_matches(t, '(\+?(?:[0-9০-৯]|(?<![A-Za-zঀ-৿])(?:three|seven|eight|শূন্য|শুন্য|সিক্স|সেভেন|ওয়ান|zero|four|five|nine|পাঁচ|জিরো|থ্রি|ফাইভ|নাইন|one|two|six|দুই|তিন|চার|পাচ|সাত|ছয়|নয়|ফোর|এইট|oh|এক|আট|টু)(?![A-Za-zঀ-৿]))(?:[\s\-–—_.,/()+​‍]*(?:[0-9০-৯]|(?<![A-Za-zঀ-৿])(?:three|seven|eight|শূন্য|শুন্য|সিক্স|সেভেন|ওয়ান|zero|four|five|nine|পাঁচ|জিরো|থ্রি|ফাইভ|নাইন|one|two|six|দুই|তিন|চার|পাচ|সাত|ছয়|নয়|ফোর|এইট|oh|এক|আট|টু)(?![A-Za-zঀ-৿])))+)', 'gi'))[1] loop
    if app.run_digits(run) ~ '(880|88)?01[3-9][0-9]{8}' then
      out := replace(out, run, '[HIDDEN]');
      hit := true;
    end if;
  end loop;
  before := out;
  out := regexp_replace(out, '(?:\+?[8৮]\s*[-()_./​‍]*\s*[0০]?\s*[-()_./​‍]*\s*[1১]|[0০]\s*[-()_./​‍]*\s*[1১]|\(?\+?[8৮]\)?\s*[-()_./​‍]*\s*[0০]?\s*[-()_./​‍]*\s*[1১])\s*[-()_./​‍]*\s*[0-9০-৯](?:\s*[-()_./​‍]*\s*[0-9০-৯]){8}', '[HIDDEN]', 'gi');
  return jsonb_build_object('text', out, 'hit', hit or out <> before);
end $$;

create or replace function app.hide_contact_routes(t text) returns jsonb
language plpgsql immutable as $$
declare out text := t;
begin
  out := regexp_replace(out, '(?:https?://)?(?:www\.)?(?:wa\.me|api\.whatsapp\.com|chat\.whatsapp\.com|t\.me|telegram\.me|m\.me|messenger\.com|viber\.com|invite\.viber\.com|imo\.im|facebook\.com|fb\.com|fb\.me|instagram\.com)(?:/[^\s]*)?', '[HIDDEN]', 'gi');
  out := regexp_replace(out, '\y(?:whatsapp|viber|tg|imo)://[^\s]*', '[HIDDEN]', 'gi');
  out := regexp_replace(out, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '[HIDDEN]', 'gi');
  out := regexp_replace(out, '\y(?:whats\s?app|wa|imo|viber|telegram|messenger)\s+(?:me|koren|korun|kor|kore|te|e|number|no\.?|id)\y', '[HIDDEN]', 'gi');
  out := regexp_replace(out, '(?:হোয়াটসঅ্যাপ|হোয়াটস অ্যাপ|ইমো|ভাইবার|টেলিগ্রাম|মেসেঞ্জার)(?:ে|তে|এ)?\s*(?:নক|কল|মেসেজ|যোগাযোগ|নম্বর|নাম্বার|আইডি)', '[HIDDEN]', 'gi');
  return jsonb_build_object('text', out, 'hit', out <> t);
end $$;

create or replace function app.detect_off_app_payment(t text) returns boolean
language sql immutable as $$
  select normalize(t, NFC) ~* any (array[
    '\y(?:bkash|b-kash|bikash|nagad|rocket|upay)\s+(?:me|you|him|her|it|kore|kor|koro|korun|kroben|diyen|den|dio|to me|send)\y',
    '\y(?:bkash|b-kash|bikash|nagad|rocket|upay|cash)\y[^.!?\n]{0,20}\ydirect(?:ly)?\y',
    '\ydirect(?:ly)?\y[^.!?\n]{0,20}\y(?:bkash|b-kash|bikash|nagad|rocket|upay|cash)\y',
    '\ysend\s+(?:me\s+)?(?:the\s+)?(?:money|taka|tk|fare)\y',
    '\y(?:pay|paying|give|giving|take|taking)\y[^.!?\n]{0,20}\ycash\y',
    '\ycash\s+(?:only|payment|in hand|on arrival|e|dite|diben)\y',
    '\y(?:in\s+)?advance\y',
    '\ypersonal\s+(?:number|no\.?|account|bkash|nagad)\y',
    '\ypay\s+(?:you|me|him|her)\s+directly\y',
    '\y(?:off[\s-]?app|outside\s+(?:the\s+)?app|without\s+(?:the\s+)?app)\y',
    'বিকাশ\s*(?:করে|করুন|কইরা|কইরেন|দিন|দেন|পাঠান)',
    'নগদে?\s*(?:পাঠান|দিন|দেন|করে)',
    'ক্যাশ',
    'নগদ\s*টাকা',
    'অগ্রিম',
    'সরাসরি\s*(?:টাকা|পেমেন্ট|দিন)',
    'হাতে\s*হাতে',
    'অ্যাপের\s*বাইরে',
    '(?:পার্সোনাল|ব্যক্তিগত)\s*(?:নম্বর|নাম্বার|বিকাশ|একাউন্ট)'
  ])
$$;

-- For notes, bios, seat-request notes and report notes.
create or replace function app.censor(t text) returns text
language sql immutable as $$
  select app.hide_contact_routes(app.hide_phones(normalize(t, NFC))->>'text')->>'text'
$$;

-- For chat. `history` is the sender's own recent messages in this chat,
-- oldest first, so a number typed a few digits at a time is still caught.
create or replace function app.guard_message(t text, history text[] default '{}') returns jsonb
language plpgsql immutable as $$
declare
  p jsonb := app.hide_phones(normalize(t, NFC));
  r jsonb := app.hide_contact_routes(p->>'text');
  out text := r->>'text';
  flags text[] := '{}';
  mine text;
  recent text := '';
  joined text;
  m text;
  h text;
  n int := coalesce(array_length(history, 1), 0);
begin
  if (p->>'hit')::boolean or (r->>'hit')::boolean then
    flags := array_append(flags, 'contact');
  end if;
  mine := app.run_digits(out);
  if mine <> '' and not (p->>'hit')::boolean then
    if n > 0 then
      foreach h in array history[greatest(1, n - 4):n] loop
        recent := recent || app.run_digits(normalize(h, NFC));
      end loop;
    end if;
    joined := recent || mine;
    m := substring(joined from '(?:880|88)?01[3-9][0-9]{8}');
    -- Only when the number is completed by this message.
    if m is not null and strpos(joined, m) + length(m) - 1 > length(recent) then
      out := regexp_replace(out, '(\+?(?:[0-9০-৯]|(?<![A-Za-zঀ-৿])(?:three|seven|eight|শূন্য|শুন্য|সিক্স|সেভেন|ওয়ান|zero|four|five|nine|পাঁচ|জিরো|থ্রি|ফাইভ|নাইন|one|two|six|দুই|তিন|চার|পাচ|সাত|ছয়|নয়|ফোর|এইট|oh|এক|আট|টু)(?![A-Za-zঀ-৿]))(?:[\s\-–—_.,/()+​‍]*(?:[0-9০-৯]|(?<![A-Za-zঀ-৿])(?:three|seven|eight|শূন্য|শুন্য|সিক্স|সেভেন|ওয়ান|zero|four|five|nine|পাঁচ|জিরো|থ্রি|ফাইভ|নাইন|one|two|six|দুই|তিন|চার|পাচ|সাত|ছয়|নয়|ফোর|এইট|oh|এক|আট|টু)(?![A-Za-zঀ-৿])))+)', '[HIDDEN]', 'gi');
      out := regexp_replace(out, '[0-9০-৯]', '[HIDDEN]', 'g');
      out := btrim(regexp_replace(out, '(\[HIDDEN\][[:space:].-]*)+', '[HIDDEN] ', 'g'));
      flags := array_append(flags, 'contact');
    end if;
  end if;
  if app.detect_off_app_payment(t) then
    flags := array_append(flags, 'payment');
  end if;
  return jsonb_build_object('text', out, 'flags', to_jsonb(flags));
end $$;
